def add(no,topic,real,m1,m2): P.append(dict(no=no,topic=topic,items=[real,m1,m2]))
def pf(n):
    f={};d=2
    while d*d<=n:
        while n%d==0: f[d]=f.get(d,0)+1;n//=d
        d+=1
    if n>1: f[n]=f.get(n,0)+1
    sup={2:'²',3:'³',4:'⁴',5:'⁵'}
    return '×'.join(f'{p}{sup.get(e,"") if e>1 else ""}' for p,e in sorted(f.items()))
# ---------- 11 ----------
def p11(intro,items,noun='ค่าสินค้า'):
    vals=[v for _,v in items]; tot=sum(vals); assert abs(tot-round(tot))<1e-9
    fv=lambda v:(f"{v:.2f}" if abs(v-round(v))>1e-9 else f"{int(v)}")
    names=" ".join(f"{n} {fv(v)} บาท" if (i<len(items)-1) else f"และ{n} {fv(v)} บาท" for i,(n,v) in enumerate(items))
    st=[];run=0
    for i,v in enumerate(vals):
        if i==0: run=v; continue
        new=run+v; st.append(f"{run:,.2f} + {v:,.2f} = {new:,.2f}"); run=new
    st.append(f"รวมเป็นเงินทั้งหมด {int(round(tot))} บาท")
    return item(intro+" "+names+f" จงหาจำนวนเงิน{noun}ทั้งหมดที่ต้องจ่าย",st,int(round(tot)))
