def coins(c,den=(10,5,2,1)):
    out=[]
    for d in den:
        k=c//d; c-=k*d
        if k: out.append((d,k))
    return out
def p12(name,note,nn,coin_v,coin_n,items,item_names,intro,pro):
    pay=note*nn; cost=sum(items); ch=pay-cost; assert ch>=0
    cs=coins(ch); n_ch=sum(k for _,k in cs); tot=coin_n+n_ch
    q=(f"{name}มีธนบัตร {note} บาท {nn} ฉบับ และเหรียญ {coin_v} บาท {coin_n} เหรียญ {intro} "
       f"{' '.join(item_names)} หาก{pro}จ่ายเงินด้วยธนบัตรทั้งหมดที่มี และขอให้ร้านทอนเงินโดยใช้เหรียญให้น้อยที่สุด อยากทราบว่าหลังจากได้รับเงินทอน {pro}จะมีเหรียญรวมกันทั้งหมดอย่างน้อยกี่เหรียญ")
    st=[f"เงินที่จ่าย = {note} × {nn} = {pay} บาท",f"ค่าของทั้งหมด = {' + '.join(map(str,items))} = {cost} บาท",f"เงินทอน = {pay} − {cost} = {ch} บาท",
        "ทอนด้วยเหรียญน้อยที่สุด: "+" + ".join(f"เหรียญ {d} บาท {k} เหรียญ" for d,k in cs)+f" รวม {n_ch} เหรียญ",
        f"เหรียญที่มีทั้งหมด = {coin_n} + {n_ch} = {tot} เหรียญ"]
    return item(q,st,tot,note="(ใช้เหรียญไทย 1, 2, 5 และ 10 บาท)")
