def p13(y1,pct,up,y3):
    delta=y1*pct//100; assert y1*pct%100==0
    y2=y1+delta if up else y1-delta; d=abs(y2-y3)
    verb='เพิ่มขึ้น' if up else 'ลดลง'
    q=f"ในปีแรก มีเงินเก็บ {fmt(y1)} บาท ปีที่สองมีเงินเก็บ{verb} {pct}% ของปีแรก และปีที่สามมีเงินเก็บ {fmt(y3)} บาท อยากทราบว่ามีเงินเก็บในปีที่สองแตกต่างจากปีที่สามกี่บาท"
    st=[f"{pct}% ของปีแรก = {fmt(y1)} × {pct}/100 = {fmt(delta)} บาท",f"ปีที่สอง = {fmt(y1)} {'+' if up else '−'} {fmt(delta)} = {fmt(y2)} บาท",f"แตกต่างจากปีที่สาม = {fmt(max(y2,y3))} − {fmt(min(y2,y3))} = {d} บาท"]
    return item(q,st,d)
