def p14(price,disc,inst,fee,extra=''):
    d1=price*disc/100; d2=price*fee/100
    a=price-d1; b=price+d2; diff=b-a; assert abs(diff-round(diff))<1e-9
    q=(f"{{}}ต้องการซื้อ{{}}ซึ่งติดราคาป้ายไว้ {fmt(price)} บาท โดยสามารถเลือกวิธีชำระเงินได้ 2 วิธี ดังนี้ วิธีที่ 1 หากชำระด้วยเงินสดเต็มจำนวน จะได้รับส่วนลด {disc}% และวิธีที่ 2 หากชำระด้วยบัตรเครดิต และผ่อนจ่าย {inst} งวด จะคิดดอกเบี้ยเพิ่มเติม {fee}%{extra} อยากทราบว่าการชำระเงินด้วยวิธีทั้งสองนี้ มียอดเงินที่ต้องชำระแตกต่างกันอยู่กี่บาท")
    st=[f"วิธีที่ 1: ลด {disc}% = {fmt(price)} × {disc}/100 = {d1:,.2f} บาท → จ่าย {fmt(price)} − {d1:,.2f} = {a:,.2f} บาท",f"วิธีที่ 2: ดอกเบี้ย {fee}% = {fmt(price)} × {fee}/100 = {d2:,.2f} บาท → จ่าย {fmt(price)} + {d2:,.2f} = {b:,.2f} บาท",f"ต่างกัน = {b:,.2f} − {a:,.2f} = {int(round(diff))} บาท",f"(ทางลัด: {disc}% + {fee}% = {disc+fee:g}% ของ {fmt(price)} = {int(round(diff))} บาท)"]
    return item(q,st,int(round(diff)),note="(ตีความดอกเบี้ย 0.6% เป็นการคิดครั้งเดียวจากราคาป้าย)")
