def p16(name,lens):
    g=reduce(gcd,lens); pc=[l//g for l in lens]
    q=f"{name}มีไม้กระดาน 3 แผ่นที่มีความยาวแตกต่างกัน โดยมีความยาว {lens[0]}, {lens[1]} และ {lens[2]} เซนติเมตร ถ้า{'เขา' if name!='ฝน' else 'เธอ'}ต้องการแบ่งไม้กระดานทั้ง 3 แผ่นให้มีความยาวเท่ากัน และยาวที่สุดเท่าที่จะทำได้ อยากทราบว่า{name}จะแบ่งไม้กระดานได้ทั้งหมดกี่แผ่น"
    st=[f"ต้องการความยาวที่ยาวที่สุดและหารทุกแผ่นลงตัว → หา ห.ร.ม.",f"{lens[0]} = {pf(lens[0])}, {lens[1]} = {pf(lens[1])}, {lens[2]} = {pf(lens[2])} → ห.ร.ม. = {g} ซม.",f"จำนวนแผ่น = {lens[0]}÷{g} + {lens[1]}÷{g} + {lens[2]}÷{g} = {pc[0]} + {pc[1]} + {pc[2]} = {sum(pc)} แผ่น"]
    return item(q,st,sum(pc))
