def p17(who,t1,t2,t3,txt3,start):
    s1,s2,s3=t1,t2,t3
    l=s1*s2//gcd(s1,s2); l=l*s3//gcd(l,s3); mins=l//60; assert l%60==0
    q=f"ในการผลิต{who} ใช้เครื่องจักรจำนวน 3 เครื่อง โดยแต่ละเครื่องมีรอบเวลาการทำงาน ดังนี้<ul><li>เครื่องจักรที่ 1 ใช้เวลา {txt3[0]} ต่อการปักโลโก้ 1 ชิ้น</li><li>เครื่องจักรที่ 2 ใช้เวลา {txt3[1]} ต่อการปักโลโก้ 1 ชิ้น</li><li>เครื่องจักรที่ 3 ใช้เวลา{txt3[2]}</li></ul>หากเครื่องจักรทั้ง 3 เครื่อง เริ่มทำงานพร้อมกันและปักโลโก้เสร็จพร้อมกันครั้งแรกในเวลา {start} น. อยากทราบว่าอีกกี่นาทีที่ทั้ง 3 เครื่องจะปักโลโก้เสร็จพร้อมกันเป็นครั้งที่สอง"
    st=[f"เปลี่ยนเป็นวินาที: เครื่องที่ 1 = {s1} วินาที, เครื่องที่ 2 = {s2} วินาที, เครื่องที่ 3 = {s3} วินาที",f"หา ค.ร.น.: {s1} = {pf(s1)}, {s2} = {pf(s2)}, {s3} = {pf(s3)} → ค.ร.น. = {fmt(l)} วินาที",f"เปลี่ยนเป็นนาที: {fmt(l)} ÷ 60 = {mins} นาที"]
    return item(q,st,mins,fs='21pt')
