def combos(s): return [c for c in itertools.combinations_with_replacement(range(1,7),3) if sum(c)==s]
import itertools
def p18(who,s):
    cs=combos(s)
    q=f"{who}โยนลูกเต๋าสามลูกพร้อมกัน โดยไม่สนใจลำดับของแต้มบนลูกเต๋าที่จะได้ อยากทราบว่าจะมีกี่วิธีที่ผลรวมของแต้มทั้งหมดเท่ากับ {s}"
    st=[f"หาชุดแต้ม 3 จำนวน (แต้ม 1–6) ที่รวมกันได้ {s} โดยไม่สนลำดับ เรียงจากน้อยไปมากเพื่อไม่ให้ซ้ำ:","  "+",  ".join("("+", ".join(map(str,c))+")" for c in cs),f"มีทั้งหมด {len(cs)} วิธี"]
    return item(q,st,len(cs))
add(18,"การนับวิธี (ไม่สนลำดับ)",p18("เอม",8),p18("ไนซ์",9),p18("บีม",7))
