def p19(a,b,tot,legs,who_a,who_b,intro,na,nb):
    # a-leg and b-leg items; tot items; legs total
    y=legs-a*tot; x=tot-y; assert y>=0 and x>=0 and legs==a*x+b*y
    st=[f"สมมติให้ทั้ง {tot} {na[2]} เป็น{who_a} จะมี{na[3]}ทั้งหมด {tot} × {a} = {a*tot} {na[3]}",f"{na[3]}ที่ขาดไป = {legs} − {a*tot} = {legs-a*tot} {na[3]}",f"{who_b} 1 {na[2]} มี{na[3]}มากกว่า {b-a} {na[3]} → มี{who_b} {legs-a*tot} ÷ {b-a} = {y} {na[2]}",f"{who_a} = {tot} − {y} = {x} {na[2]} → ต่างกัน {abs(x-y)} {na[2]}"]
    return item(intro,st,abs(x-y))
